use xiom.io;

use xiom.string;
interface Addable {
  fn add(other: &Self) -> Self;
}

type Meter = {
  value: Int;
}

fn Meter.add(self, other: &Meter) -> Meter {
  return Meter{ value: self.value + other.value };
}

fn total[T: Addable](items: &Vec[T]) -> T {
  let result = match items.get(0) { Some(v) => v, None => return result };
  let i = 1;
  while i < items.len() {
    let item = match items.get(i) { Some(v) => v, None => continue };
    result = result.add(&item);
    i = i + 1;
  }
  return result;
}

fn main() -> Int {
  let meters: Vec[Meter] = Vec[Meter].new();
  meters.push(Meter{ value: 5 });
  meters.push(Meter{ value: 10 });
  meters.push(Meter{ value: 15 });
  let t = total(&meters);
  io.println(string.int_to_str(t.value));
  return 0;
}
